
.hearts {
  display: flex;
  gap: 12px;
}

.heart-box {
  display: flex;
  align-items: center;
  gap: 5px;
}

.heart {
  font-size: 0.85rem;
}

.alice-heart {
  color: var(--c-heart-alice);
  transition: color 0.6s ease;
}

.eris-heart {
  color: var(--c-heart-eris);
  transition: color 0.6s ease;
}

.heart-info {
  display: flex;
  align-items: baseline;
  gap: 4px;
}

.heart-name {
  font-size: 0.68rem;
  color: var(--c-text-muted);
}

.heart-val {
  font-weight: 700;
  font-size: 0.9rem;
  color: var(--c-text);
  transition: color 0.6s ease;
}
