
.section {
  background: var(--c-surface);
  border: 1px solid var(--c-border);
  border-radius: 10px;
  padding: 10px;
  transition:
    background-color 0.6s ease,
    border-color 0.6s ease;
}

.section-head {
  font-size: 0.78rem;
  font-weight: 700;
  color: var(--c-primary);
  margin-bottom: 8px;
  display: flex;
  align-items: center;
  gap: 5px;
  transition: color 0.6s ease;
}

.grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
}

.cell {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.cell.wide {
  grid-column: 1 / -1;
}

.label {
  font-size: 0.68rem;
  color: var(--c-text-muted);
}

.value {
  font-size: 0.82rem;
  color: var(--c-text);
  display: flex;
  align-items: center;
  gap: 6px;
  transition: color 0.6s ease;
}

.bar-bg {
  flex: 1;
  height: 6px;
  border-radius: 3px;
  background: var(--c-border);
  overflow: hidden;
  max-width: 90px;
}

.bar {
  display: block;
  height: 100%;
  border-radius: 3px;
  background: var(--c-primary);
  transition: width 0.4s ease;
}

.empty {
  font-size: 0.78rem;
  color: var(--c-text-muted);
}

.coin {
  white-space: nowrap;
}

.items {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}

.item {
  font-size: 0.78rem;
  color: var(--c-text);
  background: var(--c-bg);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 2px 7px;
  transition:
    background-color 0.6s ease,
    border-color 0.6s ease,
    color 0.6s ease;
}
